     "ai_rom": "bè lō pă-si lō chin lè?",
     "ai_cn": "想要点什么商品？",
     "ref": "ဦးထုပ်တစ်လုံး လိုချင်ပါတယ်။",
     "ref_rom": "ó-thok tă-loun lō chin bā dè.",
     "ref_cn": "想要一顶帽子。",
     "note": "လိုချင်ပါတယ်=想要。တစ်လုံး=一顶(帽子量词)。"
